// The consignment's commodity lines. A structural group, always in scope: it
// becomes one because every field below names it in `within`. The floor is the
// model's, not the page's — a notification with no line is vacuously satisfied
// without it.

// The per-line gate. Every other field on a line reads it at the same identity
// level, so each gate is a same-frame `allowListed` with a null projection.
export const category = {
  id: 'b47e2d18-6c39-4f05-8b52-1d9c7f3e8a26',
  name: 'category',
  within: commodityLine,
  status: 'mandatory'
}

// Every line carries a quantity, whichever category it is, so this one field
// needs no gate. The service still names its categories, so the page and the
// model read one list for every field alike.
export const quantity = {
  id: 'c58f3e29-7d4a-4016-9c63-2e0d8a4f9b37',
  name: 'quantity',
  within: commodityLine,
  status: 'mandatory'
}

const appliesBecauseCategory = (field) => [
  {
    code: `obligation.${field}.applicable.becauseCategory`,
    explanation: `${field} applies on lines whose category asks for it`
  }
]

// Where the consignment comes from. One notification-level answer for
// potatoes, plants and wood alike: the statute names a different scope for
// each, but a notification carries one origin.

// The per-category narrowing — ware potatoes from four countries, conifer wood
// without bark from four others, everything else from an EU member State — is
// not a gate here. A gate reads its own frame, and `category` lives one frame
// down on each commodity line, so the narrowing is validated on the page
// against the set-owned commodities service instead.

// Where the consignment is going, or — once it is here — where it is being
// kept. One notification-level answer for every commodity type: reg 24A(2)(c)
// asks potatoes for their intended destination and reg 26(2)(b) asks plants
// and wood for the intended destination or the current location. The matter
// owed is the same one, so it is one obligation and never a gate; which of the
// three sentences a notifier is shown is the page's business, decided from the
// arrival status.

export const groups = obligations.filter((obligation) =>
  obligations.some((other) => other.within === obligation)
)

// Closures are opaque to the reachability prover, so a gate must declare
// the ids it reads — explicitly, or derivably through its helper
// metadata.

it('Should enforce commodityType when the user continues', () => {
  // A contains check, never an equality one: the test fixtures merge their
  // own entries into this module-level Set at setup.
  expect(ENFORCED_AT_CONTINUE).toContain(COMMODITY_TYPE)
})

